function setZeroes(matrix) {
  // in-place: use row 0 / col 0 themselves as the "needs zeroing" markers,
  // with col0 as a separate flag since matrix[0][0] is shared by both.
  const m = matrix.length, n = matrix[0].length;
  let col0 = 1;
  for (let i = 0; i < m; i++) {
    if (matrix[i][0] === 0) col0 = 0;
    for (let j = 1; j < n; j++) {
      if (matrix[i][j] === 0) { matrix[i][0] = 0; matrix[0][j] = 0; }
    }
  }
  // walk backwards so row 0 / col 0 still hold their marker values while
  // every OTHER cell reads them
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 1; j--) {
      if (matrix[i][0] === 0 || matrix[0][j] === 0) matrix[i][j] = 0;
    }
    if (col0 === 0) matrix[i][0] = 0;
  }
}

