        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 1; j--) {
                // If row start or col start is zero, set current cell to zero
                if (matrix[i][0] == 0 || matrix[0][j] == 0) matrix[i][j] = 0;
            }
            // Update the first column cell
            if (col0 == 0) matrix[i][0] = 0;
        }
