/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(nullptr) {}
 * };
 */
class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        ListNode* prev = nullptr; // Tracks the reversed list head
        ListNode* curr = head;    // Tracks the current traversal node

        // Traverse through all nodes
        while (curr) {
            ListNode* nextNode = curr->next; // Save next node reference
            curr->next = prev;               // Reverse pointer link
            prev = curr;                     // Move prev pointer forward
            curr = nextNode;                 // Move curr pointer forward
        }

        return prev; // prev ends up as the new head of reversed list
    }
};

