function generate(numRows) {
  const triangle = [];
  for (let r = 0; r < numRows; r++) {
    const row = new Array(r + 1).fill(1); // edges are always 1
    for (let c = 1; c < r; c++) {
      row[c] = triangle[r - 1][c - 1] + triangle[r - 1][c]; // sum of the two parents above
    }
    triangle.push(row);
  }
  return triangle;
}

