function nextPermutation(nums) {
  const n = nums.length;
  // 1. find the break point: the rightmost index where the ascending run ends
  let i = n - 2;
  while (i >= 0 && nums[i] >= nums[i + 1]) i--;

  if (i >= 0) {
    // 2. find the smallest value to the right of i that still beats nums[i]
    let j = n - 1;
    while (nums[j] <= nums[i]) j--;
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }

  // 3. the suffix after i is still descending — reverse it to make it the
  //    smallest possible ordering
  let left = i + 1, right = n - 1;
  while (left < right) {
    [nums[left], nums[right]] = [nums[right], nums[left]];
    left++; right--;
  }
}

