class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        // 1. Find the break point
        int n = nums.size(); // how many elements we are permuting
        int i = n - 2; // start one before the last index
        while (i >= 0 && nums[i] >= nums[i + 1]) { // walk left over the descending tail
            i--; // still descending -> keep going
        }

        // If break point found
        if (i >= 0) { // a pivot exists => this is not the last permutation
            // 2. Find next greater element to swap
            int j = n - 1; // hunt the successor from the far right
            while (nums[j] <= nums[i]) { // nums[j] too small to beat the pivot
                j--; // step left and try again
            }
            // Swap break point with next greater
            swap(nums[i], nums[j]); // prefix grows by the SMALLEST possible amount
        }

        // 3. Reverse the suffix to get smallest permutation
        int left = i + 1, right = n - 1; // the suffix that must become ascending
        while (left < right) { // mirror the suffix in place
            swap(nums[left], nums[right]); // swap the two ends of the window
            left++; // close in from the left
            right--; // close in from the right
        }
    }
};

