function maxSubArray(nums) {
  let maxSum = nums[0];     // seed with a REAL element, never 0 (all-negative arrays)
  let currentSum = nums[0]; // best sum of a subarray ENDING at the current index

  for (let i = 1; i < nums.length; i++) {
    const x = nums[i];
    currentSum = Math.max(x, currentSum + x); // extend the run, or abandon it and restart at x
    maxSum = Math.max(maxSum, currentSum);
  }
  return maxSum;
}

