class Solution {
public:
    int maxSubArray(vector<int>& nums) {
        int maxSum = nums[0]; // seed with a REAL element, never 0 (all-negative arrays)
        int currentSum = nums[0]; // best sum of a subarray ENDING at the current index

        // Traverse remaining elements
        for (int idx = 1; idx < (int)nums.size(); idx++) { // index 0 is already seeded, so start from the second element
            int x = nums[idx];
            currentSum = max(x, currentSum + x); // extend the old run, or abandon it and restart at x
            maxSum = max(maxSum, currentSum); // remember the best run seen anywhere so far
        }

        return maxSum; // the maximum subarray sum over the whole array
    }
};

