function sortColors(nums) {
  // Dutch national flag: low/mid/high split the array into 0s | 1s | unexplored | 2s
  let low = 0, mid = 0, high = nums.length - 1;
  while (mid <= high) {
    if (nums[mid] === 0) {
      [nums[low], nums[mid]] = [nums[mid], nums[low]];
      low++; mid++; // safe to advance mid: whatever came back was a 1
    } else if (nums[mid] === 1) {
      mid++;
    } else {
      [nums[mid], nums[high]] = [nums[high], nums[mid]];
      high--; // mid deliberately does NOT move — the swapped-in value is unexamined
    }
  }
}

