class Solution {
public:
    void sortColors(vector<int>& nums) {
        int low = 0, mid = 0, high = (int)nums.size() - 1; // boundaries of the 0s / 1s / unexplored / 2s zones

        // Sort in a single pass
        while (mid <= high) { // loop while the unexplored zone [mid..high] is non-empty
            if (nums[mid] == 0) { // a 0 belongs in the front zone
                swap(nums[low], nums[mid]); // send it to the low boundary
                low++; // the 0s zone just grew
                mid++; // safe to advance: whatever came back was a 1
            } else if (nums[mid] == 1) { // a 1 is already in its correct middle zone
                mid++; // nothing to swap, just step over it
            } else { // nums[mid] == 2
                swap(nums[mid], nums[high]); // park the 2 at the back of the array
                high--; // the 2s zone grew - and mid deliberately does NOT move
            }
        }
    }
};

