function twoSum(nums, target) {
  const lookup = new Map(); // value -> index
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (lookup.has(complement)) return [lookup.get(complement), i];
    lookup.set(nums[i], i); // store AFTER the check, so a number never pairs with itself
  }
  return [];
}

