class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int, int> lookup; // Maps value to index

        // Single pass search
        for (int i = 0; i < (int)nums.size(); i++) { // index and value together
            int complement = target - nums[i]; // the partner this number needs
            auto it = lookup.find(complement);
            if (it != lookup.end()) { // O(1) average lookup - have we already passed it?
                return {it->second, i}; // earlier index first, current index second
            }
            lookup[nums[i]] = i; // store AFTER the check so a number never pairs with itself
        }
        return {}; // no pair adds up to the target
    }
};

