class Solution {
    public int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> lookup = new HashMap<>(); // Maps value to index

        // Single pass search
        for (int i = 0; i < nums.length; i++) { // index and value together
            int complement = target - nums[i]; // the partner this number needs
            if (lookup.containsKey(complement)) { // O(1) average lookup - have we already passed it?
                return new int[]{lookup.get(complement), i}; // earlier index first, current index second
            }
            lookup.put(nums[i], i); // store AFTER the check so a number never pairs with itself
        }
        return new int[]{}; // no pair adds up to the target
    }
}

