function longestConsecutive(nums) {
  const numSet = new Set(nums); // O(1) membership, duplicates gone
  let longest = 0;
  for (const num of numSet) {
    if (!numSet.has(num - 1)) { // only start counting from a run's smallest element
      let currentNum = num, currentStreak = 1;
      while (numSet.has(currentNum + 1)) { currentNum++; currentStreak++; }
      longest = Math.max(longest, currentStreak);
    }
  }
  return longest;
}

