class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        unordered_set<int> numSet(nums.begin(), nums.end()); // Load numbers into hash set
        int longest = 0; // also the correct answer for an empty input

        for (int num : numSet) { // the set already dropped duplicates for us
            // Check if current number is start of a sequence
            if (numSet.find(num - 1) == numSet.end()) { // nothing precedes num => it is a run's smallest element
                int currentNum = num; // cursor that walks forward along this run
                int currentStreak = 1; // the run contains at least num itself

                // Count sequence size
                while (numSet.find(currentNum + 1) != numSet.end()) { // O(1) membership test, not a scan
                    currentNum++; // the next number exists - extend
                    currentStreak++; // ...and count it
                }
                longest = max(longest, currentStreak); // each run is measured exactly once, from its start
            }
        }

        return longest; // length of the longest consecutive run
    }
};

