/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(nullptr) {}
 * };
 */
class Solution {
public:
    bool hasCycle(ListNode *head) {
        ListNode *slow = head; // tortoise: one node per turn
        ListNode *fast = head; // hare: two nodes per turn

        while (fast && fast->next) { // test fast before fast->next - short-circuits safely
            slow = slow->next; // tortoise crawls
            fast = fast->next->next; // hare sprints; safe because of the guard above

            if (slow == fast) return true; // pointer equality compares IDENTITY, not value - same node twice means the hare lapped the tortoise
        }

        return false; // fell off the tail, so the list terminates
    }
};

