class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        sort(nums.begin(), nums.end()); // sort array first
        vector<vector<int>> res; // collects the unique triplets
        int n = (int)nums.size();

        for (int i = 0; i < n - 2; i++) { // i anchors the first value; need two more after it
            if (i > 0 && nums[i] == nums[i - 1]) continue; // same anchor value as last time - skip it, or we'd emit duplicate triplets

            int left = i + 1, right = n - 1; // two-pointer window over the sorted suffix
            while (left < right) { // squeeze until the pointers meet
                long long s = (long long)nums[i] + nums[left] + nums[right]; // the current candidate sum
                if (s < 0) {
                    left++; // too small: only a bigger left value can help
                } else if (s > 0) {
                    right--; // too big: only a smaller right value can help
                } else {
                    res.push_back({nums[i], nums[left], nums[right]}); // exact hit - record the triplet
                    while (left < right && nums[left] == nums[left + 1]) left++; // collapse a run of equal left values...advancing to its last copy
                    while (left < right && nums[right] == nums[right - 1]) right--; // collapse a run of equal right values...retreating to its last copy
                    left++; // both pointers must move after a hit...
                    right--; // ...or we would just rebuild the same triplet
                }
            }
        }
        return res; // every unique zero-sum triplet
    }
};

