class Solution {
public:
    int trap(vector<int>& height) {
        int left = 0, right = (int)height.size() - 1; // pointers start on the two outermost bars
        int leftMax = 0, rightMax = 0; // tallest wall seen so far from each side
        int ans = 0; // running total of trapped water

        while (left < right) { // sweep until the pointers meet
            if (height[left] < height[right]) { // the SHORTER side is the one whose level is already decided
                if (height[left] >= leftMax) leftMax = height[left]; // bar taller than every wall to its left? update max boundary
                else ans += leftMax - height[left]; // otherwise it sits below the left wall - accumulate trapped water
                left++; // index settled - move inward
            } else { // the right side is the limiting one
                if (height[right] >= rightMax) rightMax = height[right]; // bar taller than every wall to its right? update max boundary
                else ans += rightMax - height[right]; // otherwise it sits below the right wall - accumulate trapped water
                right--; // index settled - move inward
            }
        }

        return ans; // total units of trapped rain water
    }
};

