class Solution {
public:
    int maxMeetings(vector<int>& start, vector<int>& end) {
        int n = (int)start.size();
        vector<pair<int, int>> meetings(n); // pair start and end times together
        for (int i = 0; i < n; i++) meetings[i] = {start[i], end[i]};
        // sort meetings based on finish times
        sort(meetings.begin(), meetings.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
            return a.second < b.second;
        });

        int count = 0; // how many meetings we have booked so far
        int lastEnd = -1; // sentinel earlier than every real time, so meeting #1 always fits

        for (auto& [s, e] : meetings) { // walk the meetings in earliest-finishing order
            if (s > lastEnd) { // if start time is after the last meeting ended
                count++; // this meeting fits, so book it
                lastEnd = e; // update last meeting end marker
            }
        }

        return count; // the maximum number of meetings one room can host
    }
};

