function subsetSums(arr) {
  const sums = [];
  const n = arr.length;
  const dfs = (idx, currSum) => {
    if (idx === n) { sums.push(currSum); return; } // every element decided
    dfs(idx + 1, currSum + arr[idx]); // include arr[idx]
    dfs(idx + 1, currSum);            // exclude arr[idx]
  };
  dfs(0, 0);
  return sums.sort((a, b) => a - b); // exactly 2^n sums
}

