class Solution {
public:
    vector<int> subsetSums(vector<int>& arr) {
        sums.clear();
        n = (int)arr.size(); // reaching idx == n means every element has been decided
        dfs(arr, 0, 0); // start at element 0 with a running sum of 0
        sort(sums.begin(), sums.end()); // sort final sums in increasing order
        return sums; // exactly 2^n sums, in ascending order
    }

private:
    vector<int> sums; // one total per subset ends up here
    int n;

    void dfs(vector<int>& arr, int idx, int currSum) {
        if (idx == n) { // base case: no elements left to decide
            sums.push_back(currSum); // subset complete
            return; // this branch of the decision tree is finished
        }
        // Decision 1: include current element
        dfs(arr, idx + 1, currSum + arr[idx]);
        // Decision 2: exclude current element
        dfs(arr, idx + 1, currSum);
    }
};

