class Solution {
    private List<Integer> sums; // one total per subset ends up here
    private int n;

    public List<Integer> subsetSums(int[] arr) {
        sums = new ArrayList<>();
        n = arr.length; // reaching idx == n means every element has been decided
        dfs(arr, 0, 0); // start at element 0 with a running sum of 0
        Collections.sort(sums); // sort final sums in increasing order
        return sums; // exactly 2^n sums, in ascending order
    }

    private void dfs(int[] arr, int idx, int currSum) {
        if (idx == n) { // base case: no elements left to decide
            sums.add(currSum); // subset complete
            return; // this branch of the decision tree is finished
        }
        // Decision 1: include current element
        dfs(arr, idx + 1, currSum + arr[idx]);
        // Decision 2: exclude current element
        dfs(arr, idx + 1, currSum);
    }
}

