function permute(nums) {
  nums = [...nums];
  const ans = [];
  const backtrack = (idx) => {
    if (idx === nums.length) { ans.push([...nums]); return; } // copy — nums keeps mutating
    for (let i = idx; i < nums.length; i++) {
      [nums[idx], nums[i]] = [nums[i], nums[idx]]; // choose
      backtrack(idx + 1);                          // explore
      [nums[idx], nums[i]] = [nums[i], nums[idx]]; // unchoose
    }
  };
  backtrack(0);
  return ans; // exactly n! permutations
}

