class Solution {
public:
    vector<vector<int>> permute(vector<int>& nums) {
        vector<vector<int>> ans;  // every finished permutation is collected here
        backtrack(nums, 0, ans);
        return ans;  // exactly n! permutations
    }

private:
    void backtrack(vector<int>& nums, int idx, vector<vector<int>>& ans) {
        if (idx == (int)nums.size()) {  // all slots filled -> one complete permutation
            ans.push_back(nums);  // add a copy of current permutation
            return;  // nothing left to decide on this branch
        }
        for (int i = idx; i < (int)nums.size(); i++) {  // every value in the untouched suffix is a candidate for slot idx
            // Choose: swap index values
            swap(nums[idx], nums[i]);
            // Explore: recurse next position
            backtrack(nums, idx + 1, ans);
            // Unchoose: swap back to backtrack
            swap(nums[idx], nums[i]);
        }
    }
};

