class Solution {
    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> ans = new ArrayList<>();  // every finished permutation is collected here
        backtrack(nums, 0, ans);
        return ans;  // exactly n! permutations
    }

    private void backtrack(int[] nums, int idx, List<List<Integer>> ans) {
        if (idx == nums.length) {  // all slots filled -> one complete permutation
            List<Integer> perm = new ArrayList<>();
            for (int num : nums) perm.add(num);
            ans.add(perm);  // add a copy of current permutation
            return;  // nothing left to decide on this branch
        }
        for (int i = idx; i < nums.length; i++) {  // every value in the untouched suffix is a candidate for slot idx
            // Choose: swap index values
            int tmp = nums[idx];
            nums[idx] = nums[i];
            nums[i] = tmp;
            // Explore: recurse next position
            backtrack(nums, idx + 1, ans);
            // Unchoose: swap back to backtrack
            tmp = nums[idx];
            nums[idx] = nums[i];
            nums[i] = tmp;
        }
    }
}

