function solveNQueens(n) {
  const ans = [];
  const board = Array.from({ length: n }, () => new Array(n).fill('.'));
  // O(1) threat checks: a column, and the two diagonals a queen occupies
  const cols = new Set(), diag1 = new Set(), diag2 = new Set(); // r-c and r+c

  const backtrack = (r) => {
    if (r === n) { ans.push(board.map(row => row.join(''))); return; }
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || diag1.has(r - c) || diag2.has(r + c)) continue;
      board[r][c] = 'Q'; cols.add(c); diag1.add(r - c); diag2.add(r + c);
      backtrack(r + 1);
      board[r][c] = '.'; cols.delete(c); diag1.delete(r - c); diag2.delete(r + c);
    }
  };
  backtrack(0);
  return ans;
}

