class Solution {
public:
    vector<vector<string>> solveNQueens(int n) {
        vector<vector<string>> ans;  // every complete, conflict-free board lands here
        vector<string> board(n, string(n, '.'));  // a fresh n x n grid of empty cells

        // Sets to track threatened positions in O(1) time
        unordered_set<int> cols;
        unordered_set<int> diag1;  // r - c
        unordered_set<int> diag2;  // r + c

        backtrack(0, n, board, cols, diag1, diag2, ans);
        return ans;  // all distinct solutions for this n
    }

private:
    void backtrack(int r, int n, vector<string>& board, unordered_set<int>& cols,
                    unordered_set<int>& diag1, unordered_set<int>& diag2,
                    vector<vector<string>>& ans) {
        if (r == n) {  // every row already holds a queen
            ans.push_back(board);  // freeze the board into n strings
            return;  // this branch produced a full solution
        }

        for (int c = 0; c < n; c++) {  // try each column of row r, left to right
            if (cols.count(c) || diag1.count(r - c) || diag2.count(r + c)) {
                continue;  // threatened cell, skip
            }

            // Choose: place queen
            board[r][c] = 'Q';  // draw the queen on the board
            cols.insert(c);  // column c is now off limits
            diag1.insert(r - c);
            diag2.insert(r + c);

            // Explore: recurse next row
            backtrack(r + 1, n, board, cols, diag1, diag2, ans);  // try to complete rows r+1 .. n-1

            // Unchoose: backtrack state
            board[r][c] = '.';  // erase the queen again
            cols.erase(c);  // release column c for the sibling branches
            diag1.erase(r - c);
            diag2.erase(r + c);
        }
    }
};

