class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> ans = new ArrayList<>();  // every complete, conflict-free board lands here
        char[][] board = new char[n][n];  // a fresh n x n grid of empty cells
        for (char[] row : board) Arrays.fill(row, '.');

        // Sets to track threatened positions in O(1) time
        Set<Integer> cols = new HashSet<>();
        Set<Integer> diag1 = new HashSet<>();  // r - c
        Set<Integer> diag2 = new HashSet<>();  // r + c

        backtrack(0, n, board, cols, diag1, diag2, ans);
        return ans;  // all distinct solutions for this n
    }

    private void backtrack(int r, int n, char[][] board, Set<Integer> cols,
                            Set<Integer> diag1, Set<Integer> diag2, List<List<String>> ans) {
        if (r == n) {  // every row already holds a queen
            List<String> solution = new ArrayList<>();
            for (char[] row : board) solution.add(new String(row));  // freeze the board into n strings
            ans.add(solution);
            return;  // this branch produced a full solution
        }

        for (int c = 0; c < n; c++) {  // try each column of row r, left to right
            if (cols.contains(c) || diag1.contains(r - c) || diag2.contains(r + c)) {
                continue;  // threatened cell, skip
            }

            // Choose: place queen
            board[r][c] = 'Q';  // draw the queen on the board
            cols.add(c);  // column c is now off limits
            diag1.add(r - c);
            diag2.add(r + c);

            // Explore: recurse next row
            backtrack(r + 1, n, board, cols, diag1, diag2, ans);  // try to complete rows r+1 .. n-1

            // Unchoose: backtrack state
            board[r][c] = '.';  // erase the queen again
            cols.remove(c);  // release column c for the sibling branches
            diag1.remove(r - c);
            diag2.remove(r + c);
        }
    }
}

