class Solution {
public:
    int search(vector<int>& nums, int target) {
        int low = 0, high = (int)nums.size() - 1;  // the search window starts as the whole array

        while (low <= high) {  // keep going while the window is non-empty
            int mid = low + (high - low) / 2;  // overflow-safe midpoint of the window
            if (nums[mid] == target) {  // direct hit?
                return mid;  // values are distinct, so this is THE index
            }

            // Case 1: left half is sorted
            if (nums[low] <= nums[mid]) {
                if (nums[low] <= target && target < nums[mid]) {
                    high = mid - 1;  // search left half
                } else {
                    low = mid + 1;  // search right half
                }
            }
            // Case 2: right half is sorted
            else {
                if (nums[mid] < target && target <= nums[high]) {
                    low = mid + 1;  // search right half
                } else {
                    high = mid - 1;  // search left half
                }
            }
        }

        return -1;  // window collapsed without ever matching
    }
};

