function nextGreaterElement(nums1, nums2) {
  const greaterMap = new Map();
  const stack = []; // kept strictly decreasing
  for (const num of nums2) {
    while (stack.length && stack[stack.length - 1] < num) {
      greaterMap.set(stack.pop(), num); // num is the first greater value for whatever we just popped
    }
    stack.push(num);
  }
  return nums1.map(x => greaterMap.has(x) ? greaterMap.get(x) : -1);
}

