class Solution {
public:
    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, int> greaterMap;
        vector<int> stack;  // decreasing stack

        // Find next greater elements in nums2
        for (int num : nums2) {
            while (!stack.empty() && stack.back() < num) {
                greaterMap[stack.back()] = num;
                stack.pop_back();
            }
            stack.push_back(num);
        }

        // Map values or default to -1
        vector<int> result;
        result.reserve(nums1.size());
        for (int x : nums1) {
            auto it = greaterMap.find(x);
            result.push_back(it != greaterMap.end() ? it->second : -1);
        }
        return result;
    }
};

