class Solution {
    public int[] nextGreaterElement(int[] nums1, int[] nums2) {
        Map<Integer, Integer> greaterMap = new HashMap<>();
        Deque<Integer> stack = new ArrayDeque<>();  // decreasing stack

        // Find next greater elements in nums2
        for (int num : nums2) {
            while (!stack.isEmpty() && stack.peek() < num) {
                greaterMap.put(stack.pop(), num);
            }
            stack.push(num);
        }

        // Map values or default to -1
        int[] result = new int[nums1.length];
        for (int i = 0; i < nums1.length; i++) {
            result[i] = greaterMap.getOrDefault(nums1[i], -1);
