class Solution {
public:
    vector<int> bfsOfGraph(int V, vector<vector<int>>& adj) {
        vector<int> bfs;                  // the traversal order we will return
        vector<bool> visited(V, false);   // one O(1) flag per vertex, far cheaper than scanning a list
        queue<int> q;
        q.push(0);            // BFS queue starting at vertex 0
        visited[0] = true;    // the source counts as discovered before the loop starts

        while (!q.empty()) {  // keep going while any vertex is still scheduled
            int node = q.front(); q.pop();  // popping the OLDEST vertex is what makes this breadth-first
            bfs.push_back(node);            // record the vertex in visit order

            // Enqueue unvisited neighbors
            for (int neighbor : adj[node]) {
                if (!visited[neighbor]) {     // never enqueue the same vertex twice
                    visited[neighbor] = true; // mark at DISCOVERY time, not at pop time
                    q.push(neighbor);         // it waits behind everything already queued
                }
            }
        }

        return bfs;  // every vertex reachable from 0, in layer order
    }
};

