class Solution {
public:
    int longestCommonSubsequence(string text1, string text2) {
        int m = text1.size(), n = text2.size();  // the table dimensions come from the two string lengths
        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));  // row 0 and column 0 stay 0: an empty prefix matches nothing

        // Populate DP matrix
        for (int i = 1; i <= m; i++) {       // i = how many characters of text1 we are considering
            for (int j = 1; j <= n; j++) {   // j = how many characters of text2 we are considering
                if (text1[i - 1] == text2[j - 1]) {  // careful: dp is 1-based while the strings are 0-based
                    // Characters match -> add diagonal
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    // Discrepancy -> take best fallback
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        return dp[m][n];  // the cell for the two FULL strings is the answer
    }
};

