class Solution {
    public void rotate(int[][] matrix) {
        int n = matrix.length;  // the matrix is n x n
        // Step 1: transpose -- mirror every cell across the main diagonal
        for (int i = 0; i < n; i++) {
            // j starts at i + 1 so each pair (i,j)/(j,i) swaps exactly once
            for (int j = i + 1; j < n; j++) {
                // Swap the cell with its mirror across the diagonal
                int temp = matrix[i][j];
                matrix[i][j] = matrix[j][i];
                matrix[j][i] = temp;
            }
        }
        // Step 2: reverse every row to finish the 90-degree clockwise turn
        for (int[] row : matrix) {
            // In-place left-right flip of one row
            int left = 0, right = row.length - 1;
            while (left < right) {
                int temp = row[left];
                row[left] = row[right];
                row[right] = temp;
                left++;
                right--;
            }
        }
    }
}

