class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        // Sort by start so intervals that can overlap become neighbours
        sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[0] < b[0];
        });
        vector<vector<int>> merged;  // output list of disjoint, merged intervals
        // Sweep the sorted intervals left to right
        for (auto& interval : intervals) {
            int start = interval[0], end = interval[1];
            // Overlap test: this start falls inside (or touches) the last merged block
            if (!merged.empty() && start <= merged.back()[1]) {
                // Absorb: stretch the last block's right edge if this one reaches further
                merged.back()[1] = max(merged.back()[1], end);
            } else {
                // No overlap: this interval starts a fresh block
                merged.push_back({start, end});
            }
        }
        // Every overlapping group is now collapsed into a single interval
        return merged;
    }
};

