class Solution {
public:
    void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
        int i = m - 1;      // index of the last REAL element of nums1
        int j = n - 1;      // index of the last element of nums2
        int k = m + n - 1;  // last slot of nums1 = current write position
        // Fill nums1 from the BACK so we never overwrite an unread value
        while (j >= 0) {
            // Take the larger tail element; i < 0 means nums1 is used up
            if (i >= 0 && nums1[i] > nums2[j]) {
                nums1[k] = nums1[i];  // nums1's tail element wins this slot
                i--;                  // consume it
            } else {
                nums1[k] = nums2[j];  // nums2's element wins (or nums1 is empty)
                j--;                  // consume it
            }
            k--;  // slot filled -- move the write position one step left
        }
        // Any leftover nums1 elements are already in their correct place
    }
};

