class Solution {
public:
    vector<int> findRepeatMissing(vector<int>& nums) {
        long long n = nums.size();  // the values are supposed to be exactly 1..n
        // What the totals WOULD be if 1..n each appeared exactly once
        long long expectedSum = n * (n + 1) / 2;                 // 1 + 2 + ... + n
        long long expectedSq = n * (n + 1) * (2 * n + 1) / 6;    // 1^2 + 2^2 + ... + n^2
        long long actualSum = 0;  // running sum of the real array
        long long actualSq = 0;   // running sum of squares of the real array
        // One pass accumulates both actual totals
        for (int x : nums) {
            actualSum += x;             // add the value itself
            actualSq += (long long)x * x; // add its square
        }
        // Let R = repeated value, M = missing value. Two equations fall out:
        long long diff = actualSum - expectedSum;   // equation 1:  R - M
        long long sqDiff = actualSq - expectedSq;    // R^2 - M^2 = (R - M)(R + M)
        long long total = sqDiff / diff;             // equation 2:  R + M
        long long repeat = (diff + total) / 2;       // add the equations: 2R = diff + total
        long long missing = repeat - diff;           // back-substitute: M = R - (R - M)
        return {(int)repeat, (int)missing};  // [the twice-occurring value, the absent value]
    }
};

