class Solution {
public:
    long long inversionCount(vector<int>& arr) {
        // Kick off on the whole array; the caller only needs the count
        auto result = sortCount(arr);
        return result.second;
    }

private:
    // Merge sort counts inversions WHILE it sorts:
    // whenever a right-half element wins the merge, it jumps over
    // every remaining left-half element -> that many inversions at once.
    pair<vector<int>, long long> sortCount(vector<int>& a) {
        // Base case: 0 or 1 element can hold no inversions
        if (a.size() <= 1) return {a, 0LL};
        int mid = a.size() / 2;  // split point
        vector<int> leftHalf(a.begin(), a.begin() + mid);
        vector<int> rightHalf(a.begin() + mid, a.end());
        auto leftRes = sortCount(leftHalf);    // inversions fully inside the left half
        auto rightRes = sortCount(rightHalf);  // inversions fully inside the right half
        vector<int>& left = leftRes.first;
        vector<int>& right = rightRes.first;
        vector<int> merged;  // the sorted combination being built
        merged.reserve(a.size());
        size_t i = 0, j = 0;  // read positions in left and right
        long long inv = leftRes.second + rightRes.second;  // inversions already found inside the halves
        // Merge the two sorted halves, counting CROSS inversions
        while (i < left.size() && j < right.size()) {
            if (left[i] <= right[j]) {
                merged.push_back(left[i]);  // no inversion: left value is in order
                i++;  // consume it
            } else {
                merged.push_back(right[j]);         // right[j] beats a left value...
                inv += (long long)(left.size() - i); // ...and ALL remaining lefts are bigger too
                j++;  // consume it
            }
        }
        while (i < left.size()) merged.push_back(left[i++]);   // leftover left values (already sorted)
        while (j < right.size()) merged.push_back(right[j++]); // leftover right values (already sorted)
        return {merged, inv};
