class Solution {
    public long inversionCount(int[] arr) {
        // Kick off on the whole array; the caller only needs the count
        long[] invHolder = new long[1];
        sortCount(arr, invHolder);
        return invHolder[0];
    }

    // Merge sort counts inversions WHILE it sorts:
    // whenever a right-half element wins the merge, it jumps over
    // every remaining left-half element -> that many inversions at once.
    private int[] sortCount(int[] a, long[] invHolder) {
        // Base case: 0 or 1 element can hold no inversions
        if (a.length <= 1) return a;
        int mid = a.length / 2;  // split point
        int[] left = sortCount(Arrays.copyOfRange(a, 0, mid), invHolder);   // inversions fully inside the left half
        int[] right = sortCount(Arrays.copyOfRange(a, mid, a.length), invHolder); // inversions fully inside the right half
        int[] merged = new int[a.length];  // the sorted combination being built
        int i = 0, j = 0, k = 0;  // read positions in left and right
        // invHolder[0] already carries inversions found inside the halves via recursive calls
        while (i < left.length && j < right.length) {
            if (left[i] <= right[j]) {
                merged[k++] = left[i];  // no inversion: left value is in order
                i++;  // consume it
            } else {
                merged[k++] = right[j];             // right[j] beats a left value...
                invHolder[0] += (left.length - i);  // ...and ALL remaining lefts are bigger too
                j++;  // consume it
            }
        }
        while (i < left.length) merged[k++] = left[i++];   // leftover left values (already sorted)
        while (j < right.length) merged[k++] = right[j++]; // leftover right values (already sorted)
        return merged;
    }
}

