class Solution {
public:
    vector<int> majorityElement(vector<int>& nums) {
        // Extended Boyer-Moore: at most 2 values can exceed n/3, so keep 2 slots.
        int cand1 = 0, count1 = 0;     // first candidate slot + its vote balance
        int cand2 = 0, count2 = 0;     // second candidate slot + its vote balance
        bool has1 = false, has2 = false;
        for (int num : nums) {                 // PASS 1: find the only two POSSIBLE winners
            if (has1 && num == cand1) {         // matches slot 1 -> vote for it
                count1++;
            } else if (has2 && num == cand2) {  // matches slot 2 -> vote for it
                count2++;
            } else if (count1 == 0) {           // slot 1 is vacant -> adopt this value there
                cand1 = num; count1 = 1; has1 = true;
            } else if (count2 == 0) {           // slot 2 is vacant -> adopt this value there
                cand2 = num; count2 = 1; has2 = true;
            } else {                            // num matches neither slot and both are taken:
                count1--;                       // cancel one vote from slot 1 ...
                count2--;                       // ... and one from slot 2 (a distinct TRIPLE dies)
            }
        }
        vector<int> result;                     // PASS 2: candidates are only *possible* answers
        int threshold = (int)nums.size() / 3;   // must appear strictly more than n/3 times
        if (has1 && count(nums.begin(), nums.end(), cand1) > threshold) {
            result.push_back(cand1);
        }
        if (has2 && count(nums.begin(), nums.end(), cand2) > threshold) {
            result.push_back(cand2);
        }
        return result;                          // zero, one, or two verified values
    }
};

