class Solution {
public:
    int uniquePaths(int m, int n) {
        // Every path is exactly (m-1) downs + (n-1) rights: count the orderings.
        int total = m + n - 2;             // total moves every single path must make
        int pick = min(m - 1, n - 1);      // choose slots for the rarer move type
        long long result = 1;              // running value of C(total, pick), starts at C(x, 0)
        for (int i = 1; i <= pick; i++) {  // build C(total, i) from C(total, i-1) step by step
            result = result * (total - pick + i) / i;   // multiply first, divide exactly
        }
        return (int)result;                // C(m+n-2, min(m-1, n-1)) distinct monotone paths
    }
};

