class Solution {
public:
    int reversePairs(vector<int>& nums) {
        // Merge-sort the array and count cross pairs while both halves are sorted.
        long long count = 0;
        vector<int> arr = nums;
        sortCount(arr, count);
        return (int)count;                // the caller only needs the count
    }

private:
    // Sorts `arr` in place and adds cross-half reverse pairs into `count`.
    void sortCount(vector<int>& arr, long long& count) {
        int n = (int)arr.size();          // size of this segment
        if (n <= 1) return;               // 0 or 1 element: already sorted, no pair inside it
        int mid = n / 2;                  // split the segment down the middle
        vector<int> left(arr.begin(), arr.begin() + mid);
        vector<int> right(arr.begin() + mid, arr.end());
        sortCount(left, count);           // solve the left half
        sortCount(right, count);          // solve the right half

        int j = 0;                        // pointer into the sorted right half
        for (int x : left) {              // left values in ascending order
            while (j < (int)right.size() && (long long)x > 2LL * right[j]) {
                j++;                      // right[j] qualifies; a bigger x keeps it too
            }
            count += j;                   // first j right values pair with this x
        }

        vector<int> merged;               // now the standard merge of sorted halves
        merged.reserve(n);
        int a = 0, b = 0;                 // read heads for left and right
        while (a < (int)left.size() && b < (int)right.size()) {
            if (left[a] <= right[b]) {    // smaller front value goes out first
                merged.push_back(left[a]);
                a++;
            } else {
                merged.push_back(right[b]);
                b++;
            }
        }
        while (a < (int)left.size()) merged.push_back(left[a++]);   // leftovers already sorted
        while (b < (int)right.size()) merged.push_back(right[b++]);
        arr = merged;                     // write the sorted segment back
    }
};

