class Solution {
    private long count;

    public int reversePairs(int[] nums) {
        // Merge-sort the array and count cross pairs while both halves are sorted.
        count = 0;
        int[] arr = Arrays.copyOf(nums, nums.length);
        sortCount(arr);
        return (int) count;                // the caller only needs the count
    }

    // Sorts `arr` in place and accumulates cross-half reverse pairs into `count`.
    private void sortCount(int[] arr) {
        int n = arr.length;                // size of this segment
        if (n <= 1) return;                // 0 or 1 element: already sorted, no pair inside it
        int mid = n / 2;                   // split the segment down the middle
        int[] left = Arrays.copyOfRange(arr, 0, mid);
        int[] right = Arrays.copyOfRange(arr, mid, n);
        sortCount(left);                   // solve the left half
        sortCount(right);                  // solve the right half

        int j = 0;                         // pointer into the sorted right half
        for (int x : left) {               // left values in ascending order
            while (j < right.length && (long) x > 2L * right[j]) {
                j++;                       // right[j] qualifies; a bigger x keeps it too
            }
            count += j;                    // first j right values pair with this x
        }

        int[] merged = new int[n];         // now the standard merge of sorted halves
        int a = 0, b = 0, k = 0;           // read heads for left and right
        while (a < left.length && b < right.length) {
            if (left[a] <= right[b]) {     // smaller front value goes out first
                merged[k++] = left[a++];
            } else {
                merged[k++] = right[b++];
            }
        }
        while (a < left.length) merged[k++] = left[a++];    // leftovers already sorted
        while (b < right.length) merged[k++] = right[b++];
        System.arraycopy(merged, 0, arr, 0, n);   // write the sorted segment back
    }
}

