class Solution {
public:
    vector<vector<int>> fourSum(vector<int>& nums, int target) {
        // Sort, fix the first two numbers, close the last two with two pointers.
        sort(nums.begin(), nums.end());       // sorted order powers pointers + dedupe
        int n = (int)nums.size();             // total numbers available
        vector<vector<int>> result;           // unique quadruplets, collected in order
        for (int i = 0; i <= n - 4; i++) {    // first number needs 3 slots after it
            if (i > 0 && nums[i] == nums[i - 1]) continue;   // same first value -> only dupes
            for (int j = i + 1; j <= n - 3; j++) {           // second number needs 2 slots after it
                if (j > i + 1 && nums[j] == nums[j - 1]) continue;  // same second value -> only dupes
                long long need = (long long)target - nums[i] - nums[j];  // what the last two must sum to
                int left = j + 1, right = n - 1;   // pointers closing in from both ends
                while (left < right) {             // scan the remaining window
                    long long pair = (long long)nums[left] + nums[right];  // candidate pair sum
                    if (pair == need) {             // hit: a full quadruplet reaches target
                        result.push_back({nums[i], nums[j], nums[left], nums[right]});
                        left++;                      // step past the third number just used
                        right--;                      // and past the matching fourth number
                        while (left < right && nums[left] == nums[left - 1]) left++;    // skip dup thirds
                        while (left < right && nums[right] == nums[right + 1]) right--; // skip dup fourths
                    } else if (pair < need) {         // undershoot -> need a bigger left value
                        left++;
                    } else {                          // overshoot -> need a smaller right value
                        right--;
                    }
                }
            }
        }
        return result;                        // every unique quadruplet, sorted inside
    }
};

