class Solution {
public:
    int maxLen(vector<int>& arr) {
        // Equal prefix sums at two positions => the slice between them sums to 0.
        unordered_map<long long, int> firstSeen;   // prefix sum -> EARLIEST index
        firstSeen[0] = -1;                         // sum 0 exists "before" index 0
        long long prefix = 0;                      // running sum of arr[0..i]
        int best = 0;                               // longest zero-sum subarray length so far
        for (int i = 0; i < (int)arr.size(); i++) { // single pass over the array
            prefix += arr[i];                        // extend the running prefix sum by arr[i]
            auto it = firstSeen.find(prefix);
            if (it != firstSeen.end()) {              // same sum seen before at earlier index
                best = max(best, i - it->second);     // that whole slice sums to 0
            } else {
                firstSeen[prefix] = i;                // record the EARLIEST index for this sum
            }
        }
        return best;                                  // 0 when no zero-sum subarray exists
    }
};

