class Solution {
public:
    int countSubarraysWithXor(vector<int>& nums, int target) {
        // Running prefix XOR
        int xr = 0;
        // Frequency of prefix XORs encountered so far
        unordered_map<int, int> xrMap;
        xrMap[0] = 1;
        int count = 0;
        for (int val : nums) {
            // Prefix XOR up to the current index
            xr ^= val;
            // The target prefix XOR we look for is xr ^ target
            int need = xr ^ target;
            auto it = xrMap.find(need);
            if (it != xrMap.end()) {
                count += it->second;
            }
            // Update the frequency of the current prefix XOR
            xrMap[xr]++;
        }
        return count;
    }
};

