class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        // Last seen index of each character
        unordered_map<char, int> charMap;
        int maxLen = 0;
        // Left pointer of the sliding window
        int left = 0;
        for (int right = 0; right < (int)s.size(); right++) {
            // If the character is already in the window, shrink the window
            auto it = charMap.find(s[right]);
            if (it != charMap.end() && it->second >= left) {
                left = it->second + 1;
            }
            // Update/store the last seen index of the character
            charMap[s[right]] = right;
            // Update the maximum length of unique substring
            maxLen = max(maxLen, right - left + 1);
        }
        return maxLen;
    }
};

