class Solution {
    public int lengthOfLongestSubstring(String s) {
        // Last seen index of each character
        Map<Character, Integer> charMap = new HashMap<>();
        int maxLen = 0;
        // Left pointer of the sliding window
        int left = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            // If the character is already in the window, shrink the window
            if (charMap.containsKey(c) && charMap.get(c) >= left) {
                left = charMap.get(c) + 1;
            }
            // Update/store the last seen index of the character
            charMap.put(c, right);
            // Update the maximum length of unique substring
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }
}

