/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(nullptr) {}
 * };
 */
class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        // Dummy node handles edge cases like removing the head
        ListNode* dummy = new ListNode(0);
        dummy->next = head;
        // Fast and slow pointers both start at dummy
        ListNode* fast = dummy;
        ListNode* slow = dummy;
        // Move the fast pointer n steps ahead
        for (int i = 0; i < n; i++) {
            fast = fast->next;
        }
        // Move both pointers together until fast reaches the last node
        while (fast->next) {
            fast = fast->next;
            slow = slow->next;
        }
        // Skip the N-th node from the end
        slow->next = slow->next->next;
