        Node newHead = head.next;              // the first clone heads the answer list
        curr = head;
        while (curr != null) {
            Node clone = curr.next;            // the clone woven right after curr
            curr.next = clone.next;            // original skips its clone (chain restored)
            clone.next = (clone.next != null) ? clone.next.next : null; // clone links to the next clone
            curr = curr.next;                  // step to the next original node
        }
        return newHead;                        // fully independent deep copy
    }
}

