 *     int id;
 *     int deadline;
 *     int profit;
 *     Job(int id, int deadline, int profit) : id(id), deadline(deadline), profit(profit) {}
 * };
 */
class Solution {
public:
    vector<int> jobSequencing(vector<Job>& jobs, int n) {
        // Sort all jobs in descending order of profit
        sort(jobs.begin(), jobs.end(), [](const Job& a, const Job& b) {
            return a.profit > b.profit;
        });
        // Find the maximum deadline among all jobs
        int maxDeadline = 0;
        for (auto& job : jobs) maxDeadline = max(maxDeadline, job.deadline);
        // Create a schedule array initialized to -1 (indicating empty slot)
        vector<int> schedule(maxDeadline + 1, -1);
        int countJobs = 0;
        int totalProfit = 0;
        // Iterate through the sorted jobs
        for (auto& job : jobs) {
            // Find a free slot for this job, from its deadline down to 1
            for (int slot = job.deadline; slot > 0; slot--) {
                // If the slot is empty, schedule the job here
                if (schedule[slot] == -1) {
                    schedule[slot] = job.id;
                    countJobs++;
                    totalProfit += job.profit;
                    break;
                }
            }
        }
        return {countJobs, totalProfit};
    }
};

