/**
 * Definition for an item.
 * struct Item {
 *     int value;
 *     int weight;
 *     Item(int value, int weight) : value(value), weight(weight) {}
 * };
 */
class Solution {
public:
    double fractionalKnapsack(int W, vector<Item>& arr, int n) {
        // Sort items based on value-to-weight ratio in descending order
        sort(arr.begin(), arr.end(), [](const Item& a, const Item& b) {
            return (double)a.value / a.weight > (double)b.value / b.weight;
        });
        double totalValue = 0.0;
        // Iterate through all the sorted items
        for (int i = 0; i < n; i++) {
            // If the item fits completely in the remaining capacity
            if (arr[i].weight <= W) {
                totalValue += arr[i].value;
                W -= arr[i].weight;
            } else {
                // Add the fraction of the value corresponding to remaining capacity
                totalValue += arr[i].value * ((double)W / arr[i].weight);
                break;
            }
        }
        return totalValue;
    }
};

