public:
    vector<vector<int>> subsetsWithDup(vector<int>& nums) {
        // Sort the array so that duplicate elements are adjacent
        sort(nums.begin(), nums.end());
        vector<vector<int>> result;
        vector<int> currentSubset;
        backtrack(0, nums, currentSubset, result);
        return result;
    }
private:
    void backtrack(int start, vector<int>& nums, vector<int>& currentSubset, vector<vector<int>>& result) {
        // Append a copy of the current subset to the result
        result.push_back(currentSubset);
        // Iterate through the array starting from 'start'
        for (int i = start; i < (int)nums.size(); i++) {
            // Skip duplicates to ensure subsets are unique
            if (i > start && nums[i] == nums[i - 1]) continue;
            currentSubset.push_back(nums[i]);
            backtrack(i + 1, nums, currentSubset, result);
            // Backtrack: remove the last added element
            currentSubset.pop_back();
        }
    }
};

