        sort(candidates.begin(), candidates.end());
        vector<vector<int>> result;
        vector<int> currentCombination;
        backtrack(0, candidates, currentCombination, target, result);
        return result;
    }
private:
    void backtrack(int start, vector<int>& candidates, vector<int>& currentCombination, int remainingTarget, vector<vector<int>>& result) {
        // If target is met, we found a valid combination
        if (remainingTarget == 0) {
            result.push_back(currentCombination);
            return;
        }
        // Iterate through candidates starting from 'start' index
        for (int i = start; i < (int)candidates.size(); i++) {
            // If current candidate is greater than remaining target, we prune
            if (candidates[i] > remainingTarget) break;
            currentCombination.push_back(candidates[i]);
            // Call recursively, keeping 'i' as start since we can reuse elements
            backtrack(i, candidates, currentCombination, remainingTarget - candidates[i], result);
            // Backtrack: remove the last added candidate
            currentCombination.pop_back();
        }
    }
};

