class Solution {
public:
    vector<vector<string>> partition(string s) {
        vector<vector<string>> result;
        vector<string> current;
        backtrack(s, 0, current, result);
        return result;
    }
private:
    // Helper function to check if a string segment is a palindrome
    bool isPalindrome(const string& s, int startIdx, int endIdx) {
        while (startIdx < endIdx) {
            if (s[startIdx] != s[endIdx]) return false;
            startIdx++;
            endIdx--;
        }
        return true;
    }
    void backtrack(const string& s, int start, vector<string>& current, vector<vector<string>>& result) {
        // If we have reached the end of the string, record the partition
        if (start == (int)s.length()) {
            result.push_back(current);
            return;
        }
        // Explore all possible substring partitions starting from 'start'
        for (int i = start; i < (int)s.length(); i++) {
            // If the current substring s[start:i+1] is a palindrome
            if (isPalindrome(s, start, i)) {
                // Append the substring to the current partition path
                current.push_back(s.substr(start, i - start + 1));
                // Recurse for the remaining substring starting at index i + 1
                backtrack(s, i + 1, current, result);
                // Backtrack: remove the last added substring
                current.pop_back();
            }
        }
    }
};

