class Solution {
public:
    void solveSudoku(vector<vector<char>>& board) {
        solve(board);
    }
private:
    // Helper function to check if placing char 'c' is valid
    bool isValid(vector<vector<char>>& board, int row, int col, char c) {
        for (int i = 0; i < 9; i++) {
            // Check column for duplicate
            if (board[i][col] == c) return false;
            // Check row for duplicate
            if (board[row][i] == c) return false;
            // Check 3x3 box for duplicate
            int boxRow = 3 * (row / 3) + i / 3;
            int boxCol = 3 * (col / 3) + i % 3;
            if (board[boxRow][boxCol] == c) return false;
        }
        return true;
    }
    // Main recursive solver function
    bool solve(vector<vector<char>>& board) {
        for (int i = 0; i < (int)board.size(); i++) {
            for (int j = 0; j < (int)board[0].size(); j++) {
                // Check if cell is empty
                if (board[i][j] == '.') {
                    // Try placing characters '1' to '9'
                    for (char c = '1'; c <= '9'; c++) {
                        // If valid to place
                        if (isValid(board, i, j, c)) {
                            // Place character on the board
                            board[i][j] = c;
                            // Recurse to solve next cells
                            if (solve(board)) return true;
                            // Backtrack: reset cell if it fails later
                            board[i][j] = '.';
                        }
                    }
                    // Return false if no character 1-9 fits here
                    return false;
                }
            }
        }
        // Board is completely solved
        return true;
    }
};

