class Solution {
public:
    vector<string> findPath(vector<vector<int>>& m, int n) {
        vector<string> result;
        // Edge Case: If start or end cell is blocked, return empty list
        if (m[0][0] == 0 || m[n - 1][n - 1] == 0) return result;
        vector<vector<bool>> visited(n, vector<bool>(n, false));
        visited[0][0] = true;
        solve(m, n, 0, 0, "", visited, result);
        return result;
    }

private:
    void solve(vector<vector<int>>& m, int n, int row, int col, string path,
                vector<vector<bool>>& visited, vector<string>& result) {
        // Base Case: If destination is reached, add path to results
        if (row == n - 1 && col == n - 1) {
            result.push_back(path);
            return;
        }
        // Direction chars and corresponding row/col offsets
        // Standard order: D (Down), L (Left), R (Right), U (Up)
        static const int dRow[] = {1, 0, 0, -1};
        static const int dCol[] = {0, -1, 1, 0};
        static const char dirChar[] = {'D', 'L', 'R', 'U'};
        for (int d = 0; d < 4; d++) {
            int nextRow = row + dRow[d];
            int nextCol = col + dCol[d];
            // Check if the next cell is inside boundaries, not visited, and open (1)
            if (nextRow >= 0 && nextRow < n && nextCol >= 0 && nextCol < n) {
                if (!visited[nextRow][nextCol] && m[nextRow][nextCol] == 1) {
                    visited[nextRow][nextCol] = true;
                    solve(m, n, nextRow, nextCol, path + dirChar[d], visited, result);
                    visited[nextRow][nextCol] = false;
                }
            }
        }
    }
};

