class Solution {
public:
    int nthRoot(int n, int m) {
        // Set search range for binary search
        long low = 1, high = m;
        // Perform binary search
        while (low <= high) {
            long mid = (low + high) / 2;
            int midState = check(mid, n, m);
            // If mid^n is exactly m, we found the integer root
            if (midState == 1) return (int)mid;
            // If mid^n is less than m, search higher half
            else if (midState == 0) low = mid + 1;
            // If mid^n is greater than m, search lower half
            else high = mid - 1;
        }
        // No integer Nth root found
        return -1;
    }

private:
    // Helper function to check state of mid^n compared to m
    // Returns:
    // 0 if mid^n < m
    // 1 if mid^n == m
    // 2 if mid^n > m
    int check(long mid, int n, int m) {
        long ans = 1;
        for (int i = 1; i <= n; i++) {
            ans = ans * mid;
            if (ans > m) return 2;
        }
        if (ans == m) return 1;
        return 0;
    }
};

