class Solution {
public:
    int findMedian(vector<vector<int>>& matrix) {
        int R = matrix.size();
        int C = matrix[0].size();
        // The search space is bounded by the minimum and maximum elements in matrix
        // Since rows are sorted, min is in first column, max is in last column
        int low = matrix[0][0];
        int high = matrix[0][C - 1];
        for (int i = 0; i < R; i++) {
            low = min(low, matrix[i][0]);
            high = max(high, matrix[i][C - 1]);
        }
        // The target number of elements we want to be <= median
        int requiredCount = (R * C) / 2;
        // Binary search range on values
        while (low < high) {
            int mid = low + (high - low) / 2;
            // Count how many elements in the matrix are <= mid
            if (countLessEqual(matrix, R, mid) <= requiredCount) {
                // Median must be strictly greater than mid
                low = mid + 1;
            } else {
                // Median is <= mid
                high = mid;
            }
        }
        // 'low' will converge to the median
        return low;
    }

private:
    // Helper function to count elements <= x in the entire matrix
    int countLessEqual(vector<vector<int>>& matrix, int R, int x) {
        int count = 0;
        for (int i = 0; i < R; i++) {
            // Use binary search to find index of first element > x in row i
            count += (int)(upper_bound(matrix[i].begin(), matrix[i].end(), x) - matrix[i].begin());
        }
        return count;
    }
};

