class Solution {
public:
    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        // Ensure nums1 is the smaller array to optimize binary search complexity
        if (nums1.size() > nums2.size()) {
            return findMedianSortedArrays(nums2, nums1);
        }

        int m = nums1.size();
        int n = nums2.size();
        int low = 0, high = m;

        // Binary search on the smaller array
        while (low <= high) {
            // Partition point for nums1
            int partition1 = (low + high) / 2;
            // Partition point for nums2 to keep left half size balanced
            int partition2 = (m + n + 1) / 2 - partition1;

            // Edge cases: if partition is 0, use negative infinity.
            // If partition is at array length, use positive infinity.
            int maxLeft1 = (partition1 == 0) ? INT_MIN : nums1[partition1 - 1];
            int minRight1 = (partition1 == m) ? INT_MAX : nums1[partition1];

            int maxLeft2 = (partition2 == 0) ? INT_MIN : nums2[partition2 - 1];
            int minRight2 = (partition2 == n) ? INT_MAX : nums2[partition2];

            // Check if we found the correct partition
            if (maxLeft1 <= minRight2 && maxLeft2 <= minRight1) {
                // If total length is odd
                if ((m + n) % 2 == 1) {
                    return (double)max(maxLeft1, maxLeft2);
                } else {
                    // If total length is even
                    return (max(maxLeft1, maxLeft2) + min(minRight1, minRight2)) / 2.0;
                }
            } else if (maxLeft1 > minRight2) {
                // If nums1 partition is too far right
                high = partition1 - 1;
            } else {
                // If nums1 partition is too far left
                low = partition1 + 1;
            }
        }

        // Default return value (should not be reached if inputs are sorted)
        return 0.0;
    }
};

