class MyStack {
    // Use a Queue as the underlying queue (offer at back, poll from front, both O(1))
    private Queue<Integer> q;

    public MyStack() {
        q = new LinkedList<>();
    }

    public void push(int x) {
        // Add element to the queue
        q.offer(x);
        // Rotate all previous elements to the back of the queue
        int size = q.size();
        for (int i = 0; i < size - 1; i++) {
            q.offer(q.poll()); // take the front element and send it to the back
        }
    }

    public int pop() {
        // Remove and return the front element of the queue
        if (q.isEmpty()) return -1;
        return q.poll(); // after push's rotation the front IS the newest element
    }

    public int top() {
        // Peek and return the front element of the queue
        if (q.isEmpty()) return -1;
        return q.peek(); // same element pop would return, but left in place
    }

    public boolean empty() {
        // Return true if queue length is 0
        return q.isEmpty();
    }
}

