// NOT faster than sorting: this is O(N^2), while a normal sort would be
// O(N log N). It exists because the problem forbids any container other than
// the stack itself, so we must sort using only push/pop and recursion frames.
class Solution {
    public void sortStack(List<Integer> stack) {
        // Base case: if stack is empty, it is already sorted
        if (stack.isEmpty()) return;
        // Pop the top element
        int temp = stack.remove(stack.size() - 1);
        // Sort the remaining stack recursively
        sortStack(stack);
        // Insert the popped element back in sorted order
        sortedInsert(stack, temp);
    }

    private void sortedInsert(List<Integer> stack, int element) {
        // Base case: if stack is empty or element is greater than top element
        if (stack.isEmpty() || element > stack.get(stack.size() - 1)) {
            stack.add(element);
            return;
        }
        // Pop the top element if it is greater than the element to insert
        int temp = stack.remove(stack.size() - 1);
        // Recursively insert the element in the remaining stack
        sortedInsert(stack, element);
        // Push the popped element back to the stack
        stack.add(temp);
    }
}

