class Solution {
public:
    // O(n): every element is the minimum of one widest span
    vector<int> maxOfMin(vector<int>& arr) {
        int n = arr.size();
        vector<int> left(n, -1);
        vector<int> right(n, n);
        vector<int> stk;
        for (int i = 0; i < n; i++) {
            while (!stk.empty() && arr[stk.back()] >= arr[i]) {
                stk.pop_back();
            }
            if (!stk.empty()) {
                left[i] = stk.back();
            }
            stk.push_back(i);
        }
        stk.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stk.empty() && arr[stk.back()] >= arr[i]) {
                stk.pop_back();
            }
            if (!stk.empty()) {
                right[i] = stk.back();
            }
            stk.push_back(i);
        }
        vector<int> ans(n + 1, 0);
        for (int i = 0; i < n; i++) {
            int length = right[i] - left[i] - 1;
            ans[length] = max(ans[length], arr[i]);
        }
        for (int i = n - 1; i >= 1; i--) {
            ans[i] = max(ans[i], ans[i + 1]);
        }
        return vector<int>(ans.begin() + 1, ans.end());
    }
};

