class Solution {
public:
    int largestRectangleArea(vector<int>& heights) {
        vector<int> stack;
        int maxArea = 0;
        int n = heights.size();
        for (int i = 0; i <= n; i++) {
            int currentHeight = (i < n) ? heights[i] : 0;
            while (!stack.empty() && heights[stack.back()] > currentHeight) {
                int h = heights[stack.back()];
                stack.pop_back();
                int w = stack.empty() ? i : i - stack.back() - 1;
                maxArea = max(maxArea, h * w);
            }
            stack.push_back(i);
        }
        return maxArea;
    }
};

