class Solution {
public:
    int rabinKarp(string text, string pattern) {
        int n = text.size(), m = pattern.size();
        if (m > n) return -1;

        int base = 256;
        int prime = 101;
        long long h = 1;

        for (int i = 0; i < m - 1; i++) {
            h = (h * base) % prime;
        }

        long long pHash = 0, tHash = 0;
        for (int i = 0; i < m; i++) {
            pHash = (base * pHash + (unsigned char)pattern[i]) % prime;
            tHash = (base * tHash + (unsigned char)text[i]) % prime;
        }

        for (int i = 0; i <= n - m; i++) {
            if (pHash == tHash) {
                if (text.substr(i, m) == pattern) {
                    return i;
                }
            }
            if (i < n - m) {
                tHash = (base * (tHash - (long long)(unsigned char)text[i] * h) + (unsigned char)text[i + m]) % prime;
                if (tHash < 0) tHash += prime;
            }
        }

        return -1;
    }
};

