public:
    int lengthOfLIS(vector<int>& nums) {
        vector<int> tails; // tails[k] = smallest possible last value of a length-(k+1) chain
        for (int x : nums) { // a single left-to-right pass over the input
            // Binary search to find candidate slot
            auto it = lower_bound(tails.begin(), tails.end(), x);
            if (it == tails.end()) { // x beats every tail, so the longest chain can grow
                tails.push_back(x); // the answer length increases by one
            } else { // otherwise x fits somewhere inside the existing tails
                *it = x; // replace tails value with smaller candidate
            }
        }
        return tails.size(); // only the LENGTH is guaranteed; tails may not be a real LIS
    }
