class Solution {
    public int lengthOfLIS(int[] nums) {
        int[] tails = new int[nums.length]; // tails[k] = smallest possible last value of a length-(k+1) chain
        int size = 0;
        for (int x : nums) { // a single left-to-right pass over the input
            // Binary search to find candidate slot
            int idx = lowerBound(tails, size, x);
            if (idx == size) { // x beats every tail, so the longest chain can grow
                tails[size++] = x; // the answer length increases by one
            } else { // otherwise x fits somewhere inside the existing tails
                tails[idx] = x; // replace tails value with smaller candidate
            }
        }
        return size; // only the LENGTH is guaranteed; tails may not be a real LIS
    }

    private int lowerBound(int[] arr, int size, int target) {
        int lo = 0, hi = size;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

