        for (char c : word) { // one trie level per character of the word
            if (curr->children.find(c) == curr->children.end()) { // add child if not present
                curr->children[c] = new TrieNode();
            }
            curr = curr->children[c]; // step down; existing paths get REUSED
        }
        curr->isWord = true; // mark end of word
    }

