        TrieNode* curr = root; // same walk as insert, but nothing is ever created
        for (char c : word) {
            if (curr->children.find(c) == curr->children.end()) { // path breaks -> word was never inserted
                return false;
            }
            curr = curr->children[c];
        }
        return curr->isWord; // must be exact word
    }

