        for (char c : word.toCharArray()) { // one trie level per character of the word
            curr.children.putIfAbsent(c, new TrieNode()); // add child if not present
            curr = curr.children.get(c); // step down; existing paths get REUSED
        }
        curr.isWord = true; // mark end of word
    }

    public boolean search(String word) {
        TrieNode curr = root; // same walk as insert, but nothing is ever created
        for (char c : word.toCharArray()) {
            if (!curr.children.containsKey(c)) { // path breaks -> word was never inserted
                return false;
            }
            curr = curr.children.get(c);
        }
        return curr.isWord; // must be exact word
    }

    public boolean startsWith(String prefix) {
        TrieNode curr = root; // identical walk; only the final answer differs
        for (char c : prefix.toCharArray()) {
            if (!curr.children.containsKey(c)) { // prefix path breaks -> nothing starts with it
                return false;
            }
            curr = curr.children.get(c);
        }
        return true; // prefix path exists
    }

    private static class TrieNode { // one node = one position inside some word's spelling
        Map<Character, TrieNode> children = new HashMap<>();
        boolean isWord = false; // true only if an inserted word ENDS here
    }
}

