        dfs(root, maxSum);
        return maxSum;
    }

private:
    // Returns max gain this node can contribute upward to its parent.
    int dfs(TreeNode* node, int& maxSum) {
        if (!node) return 0; // base case: null contributes nothing
        // ignore negative contributions from either side
        int leftGain = max(dfs(node->left, maxSum), 0);
        int rightGain = max(dfs(node->right, maxSum), 0);
        // path sum passing through current node as the LCA/top of path
        int currentPathSum = node->val + leftGain + rightGain;
        maxSum = max(maxSum, currentPathSum);
        // only one branch can be extended upward
        return node->val + max(leftGain, rightGain);
    }
};

