public:
    vector<vector<int>> zigzagLevelOrder(TreeNode* root) { // write each level straight into its final order, no second pass
        vector<vector<int>> result;
        if (!root) return result;
        queue<TreeNode*> q; // popleft() is O(1) with a deque/queue
        q.push(root);
        bool leftToRight = true; // direction flag: true means left to right
        while (!q.empty()) {
            int levelSize = q.size();
            vector<int> levelNodes(levelSize); // fixed-size slot for current level nodes
            for (int i = 0; i < levelSize; i++) {
                TreeNode* curr = q.front();
                q.pop();
                // find correct position to insert current node val
                int index = leftToRight ? i : (levelSize - 1 - i);
                levelNodes[index] = curr->val;
                if (curr->left) q.push(curr->left);
                if (curr->right) q.push(curr->right);
            }
            result.push_back(levelNodes);
            leftToRight = !leftToRight; // toggle direction for next level
        }
        return result;
    }
};

