        return !node->left && !node->right;
    }
    // Helper to collect left boundary nodes (excluding leaves)
    void addLeftBoundary(TreeNode* node, vector<int>& res) {
        TreeNode* curr = node;
        while (curr) {
            if (!isLeaf(curr)) res.push_back(curr->val);
            // Move left if possible, else move right
            curr = curr->left ? curr->left : curr->right;
        }
    }
    // Helper to collect all leaf nodes recursively
    void addLeaves(TreeNode* node, vector<int>& res) {
        if (!node) return;
        if (isLeaf(node)) {
            res.push_back(node->val);
            return;
        }
        addLeaves(node->left, res);
        addLeaves(node->right, res);
    }
    // Helper to collect right boundary nodes in reverse
    void addRightBoundary(TreeNode* node, vector<int>& res) {
        TreeNode* curr = node;
        vector<int> temp;
        while (curr) {
            if (!isLeaf(curr)) temp.push_back(curr->val);
            // Move right if possible, else move left
            curr = curr->right ? curr->right : curr->left;
        }
        // Add right boundary nodes to result in reverse order
        for (int i = (int)temp.size() - 1; i >= 0; i--) res.push_back(temp[i]);
    }
};

