        if (root == null) return result;
        // Add root if it is not a leaf node
        if (!isLeaf(root)) result.add(root.val);
        // 1. Add left boundary nodes
        addLeftBoundary(root.left, result);
        // 2. Add all leaf nodes
        addLeaves(root, result);
        // 3. Add right boundary nodes
        addRightBoundary(root.right, result);
        return result;
    }

    private boolean isLeaf(TreeNode node) {
        return node.left == null && node.right == null;
    }

    private void addLeftBoundary(TreeNode node, List<Integer> res) {
        TreeNode curr = node;
        while (curr != null) {
            if (!isLeaf(curr)) res.add(curr.val);
            curr = curr.left != null ? curr.left : curr.right;
        }
    }

    private void addLeaves(TreeNode node, List<Integer> res) {
        if (node == null) return;
        if (isLeaf(node)) {
            res.add(node.val);
            return;
        }
        addLeaves(node.left, res);
        addLeaves(node.right, res);
    }

    private void addRightBoundary(TreeNode node, List<Integer> res) {
        TreeNode curr = node;
        List<Integer> temp = new ArrayList<>();
        while (curr != null) {
            if (!isLeaf(curr)) temp.add(curr.val);
            curr = curr.right != null ? curr.right : curr.left;
        }
        for (int i = temp.size() - 1; i >= 0; i--) res.add(temp.get(i));
    }
}

