class Solution {
public:
    void changeTree(TreeNode* root) {
        // Base case: if root is None, return
        if (!root) return;
        // Base case: if it is a leaf node, return
        if (!root->left && !root->right) return;
        // Calculate sum of children
        int childSum = 0;
        if (root->left) childSum += root->left->val;
        if (root->right) childSum += root->right->val;
        // If parent's value is greater than sum of children, lift the children
        if (root->val > childSum) {
            if (root->left) root->left->val = root->val;
            if (root->right) root->right->val = root->val;
        }
        // Recurse on left and right subtrees
        changeTree(root->left);
        changeTree(root->right);
        // Post-order update of parent value: recompute AFTER children were fixed
        int totSum = 0;
        if (root->left) totSum += root->left->val;
        if (root->right) totSum += root->right->val;
        root->val = totSum;
    }
};

