            if (parent != null && !visited.contains(parent)) {
                visited.add(parent);
                nodeQueue.add(parent);
                timeQueue.add(time + 1);
            }
        }
        return maxTime;
    }

    // Finds the target node and maps every node to its parent in one pass
    private void dfs(TreeNode node, TreeNode parent, int targetVal, Map<TreeNode, TreeNode> parentMap) {
        if (node == null) return;
        if (node.val == targetVal) targetNode = node;
        parentMap.put(node, parent);
        dfs(node.left, node, targetVal, parentMap);
        dfs(node.right, node, targetVal, parentMap);
    }
}

