/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int countNodes(TreeNode* root) {
        // An empty subtree contributes nothing to the count
        if (!root) return 0;
        // Two O(log n) probes decide whether we can skip the walk
        int lh = getLeftHeight(root);
        int rh = getRightHeight(root);
        // Equal spines mean the last level is completely filled
        if (lh == rh) return (1 << lh) - 1;  // the core trick: 2^lh - 1 nodes counted in O(1)
        // Otherwise recurse; only one child can be imperfect
        return 1 + countNodes(root->left) + countNodes(root->right);
    }
private:
    // Left spine: the longest path a complete tree can have
    int getLeftHeight(TreeNode* node) {
        int h = 0;
        while (node) {
            h++;
            node = node->left;
        }
        return h;
    }
    // Right spine: the shortest path, it stops at the gap
    int getRightHeight(TreeNode* node) {
        int h = 0;
        while (node) {
            h++;
            node = node->right;
        }
        return h;
    }
};

