        // Get current root value
        int rootVal = preorder[preIdx];
        // Create root node
        TreeNode* root = new TreeNode(rootVal);
        // Increment preorder index
        preIdx++;
        // Find index of root in inorder array
        int rootIdx = inMap[rootVal];
        // Build left subtree, then right subtree
        root->left = helper(inStart, rootIdx - 1, preorder, inMap);
