class Solution {
    public int largestBst(TreeNode root) {
        return solve(root).size;
    }

    private static class Report {
        int size;
        long min;
        long max;
        Report(int size, long min, long max) {
            this.size = size;
            this.min = min;
            this.max = max;
        }
    }

    private Report solve(TreeNode node) {
        if (node == null) return new Report(0, Long.MAX_VALUE, Long.MIN_VALUE);
        Report l = solve(node.left);
        Report r = solve(node.right);
        if (l.max < node.val && node.val < r.min) {
            return new Report(l.size + r.size + 1, Math.min(l.min, node.val), Math.max(r.max, node.val));
        }
        return new Report(Math.max(l.size, r.size), Long.MIN_VALUE, Long.MAX_VALUE);
    }
}

