            for (auto& [v, w] : adj[u]) {
                if (!visited[v]) dfs(v);
            }
            order.push_back(u);
        };
        for (int u = 0; u < V; u++) {
            if (!visited[u]) dfs(u);
        }
        reverse(order.begin(), order.end());
        const int INF = INT_MAX;
        vector<int> dist(V, INF);
        dist[src] = 0;
        for (int u : order) {
            if (dist[u] != INF) {
                for (auto& [v, w] : adj[u]) {
                    if (dist[u] + w < dist[v]) {
                        dist[v] = dist[u] + w;
                    }
                }
            }
        }
        vector<int> result(V);
        for (int i = 0; i < V; i++) {
            result[i] = (dist[i] == INF) ? -1 : dist[i];
        }
