            heap.pop();
            if (visited[u]) continue;
            visited[u] = true;
            total += w;
            count++;
            for (auto& [v, wt] : adj[u]) {
                if (!visited[v]) {
                    heap.push({wt, v});
                }
            }
        }
        return total;
    }
