class Solution {
private:
    vector<int> parent;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

public:
    int spanningTree(int V, vector<vector<int>>& edges) {
        parent.resize(V);
        for (int i = 0; i < V; i++) parent[i] = i;
        vector<int> rnk(V, 0);
        vector<vector<int>> sortedEdges = edges;
        sort(sortedEdges.begin(), sortedEdges.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[2] < b[2];
        });
        int total = 0;
        int used = 0;
        for (auto& e : sortedEdges) {
            int u = e[0], v = e[1], w = e[2];
            int ru = find(u), rv = find(v);
            if (ru == rv) continue;
            if (rnk[ru] < rnk[rv]) swap(ru, rv);
            parent[rv] = ru;
            if (rnk[ru] == rnk[rv]) rnk[ru]++;
            total += w;
            used++;
            if (used == V - 1) break;
        }
        return total;
    }
};

