class LFUCache {
public:
    LFUCache(int capacity) : cap(capacity), minFreq(0) {}

    int get(int key) {
        if (keyVal.find(key) == keyVal.end()) return -1;
        bump(key);
        return keyVal[key];
    }

    void put(int key, int value) {
        if (cap <= 0) return;
        if (keyVal.count(key)) {
            keyVal[key] = value;
            bump(key);
            return;
        }
        if ((int)keyVal.size() >= cap) {
            int victim = freqKeys[minFreq].front();
            freqKeys[minFreq].pop_front();
            keyIter.erase(victim);
            keyVal.erase(victim);
            keyFreq.erase(victim);
            if (freqKeys[minFreq].empty()) freqKeys.erase(minFreq);
        }
        keyVal[key] = value;
        keyFreq[key] = 1;
        freqKeys[1].push_back(key);
        keyIter[key] = prev(freqKeys[1].end());
        minFreq = 1;
    }

private:
    int cap;
    int minFreq;
    unordered_map<int, int> keyVal;
    unordered_map<int, int> keyFreq;
    unordered_map<int, list<int>> freqKeys;
    unordered_map<int, list<int>::iterator> keyIter;

    void bump(int key) {
        int f = keyFreq[key];
        freqKeys[f].erase(keyIter[key]);
        if (freqKeys[f].empty()) {
            freqKeys.erase(f);
            if (minFreq == f) minFreq = f + 1;
        }
        keyFreq[key] = f + 1;
        freqKeys[f + 1].push_back(key);
        keyIter[key] = prev(freqKeys[f + 1].end());
    }
};

