class LFUCache {
    private int cap;
    private int minFreq;
    private Map<Integer, Integer> keyVal = new HashMap<>();
    private Map<Integer, Integer> keyFreq = new HashMap<>();
    private Map<Integer, LinkedHashMap<Integer, Integer>> freqKeys = new HashMap<>();

    public LFUCache(int capacity) {
        this.cap = capacity;
        this.minFreq = 0;
    }

    private void bump(int key) {
        int f = keyFreq.get(key);
        LinkedHashMap<Integer, Integer> bucket = freqKeys.get(f);
        bucket.remove(key);
        if (bucket.isEmpty()) {
            freqKeys.remove(f);
            if (minFreq == f) minFreq = f + 1;
        }
        keyFreq.put(key, f + 1);
        freqKeys.computeIfAbsent(f + 1, k -> new LinkedHashMap<>()).put(key, null);
    }

    public int get(int key) {
        if (!keyVal.containsKey(key)) return -1;
        bump(key);
        return keyVal.get(key);
    }

    public void put(int key, int value) {
        if (cap <= 0) return;
        if (keyVal.containsKey(key)) {
            keyVal.put(key, value);
            bump(key);
            return;
        }
        if (keyVal.size() >= cap) {
            LinkedHashMap<Integer, Integer> bucket = freqKeys.get(minFreq);
            int victim = bucket.keySet().iterator().next();
            bucket.remove(victim);
            keyVal.remove(victim);
            keyFreq.remove(victim);
            if (bucket.isEmpty()) freqKeys.remove(minFreq);
        }
        keyVal.put(key, value);
        keyFreq.put(key, 1);
        freqKeys.computeIfAbsent(1, k -> new LinkedHashMap<>()).put(key, null);
        minFreq = 1;
    }
}

