class Solution {
public:
    vector<string> powerSet(string s) {
        int n = s.size();
        vector<string> result;
        for (int mask = 1; mask < (1 << n); mask++) {
            string pick;
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) {
                    pick.push_back(s[i]);
                }
            }
            result.push_back(pick);
        }
        sort(result.begin(), result.end());
        return result;
    }
};

