        for (int mask = 1; mask < (1 << n); mask++) {
            StringBuilder pick = new StringBuilder();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    pick.append(s.charAt(i));
                }
            }
            result.add(pick.toString());
        }
        Collections.sort(result);
        return result;
    }
